mapper.select:
SELECT id, tenant_id, file_md5, model_code, chunk_strategy,
       cache_result_markdown, expire_time, create_time
FROM prd_task_cache
WHERE tenant_id = #{tenantId}
  AND file_md5 = #{fileMd5}
  AND model_code = #{modelCode}
  AND chunk_strategy = #{chunkStrategy}
  AND expire_time > #{now}
ORDER BY id DESC
LIMIT 1
